"use strict";
const http = require('http');
const crypto = require('crypto');

const ROLES = Object.freeze({
  ADMIN: 'admin',
  USER: 'user',
  AUDITOR: 'auditor'
});

const ADMIN_ACTIONS = Object.freeze(['delete_user', 'modify_config', 'reset_system']);

// Constant-time comparison helper that also safely handles missing/invalid inputs
function safeTokenEqual(provided, expected) {
  if (typeof provided !== 'string' || typeof expected !== 'string') return false;
  if (expected.length === 0) return false; // reject when secret is unset/empty
  const a = Buffer.from(provided);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

class SessionStore {
  constructor() {
    this.sessions = new Map();
  }

  createSession(userId, role) {
    const sessionId = crypto.randomBytes(32).toString('hex');
    this.sessions.set(sessionId, Object.freeze({ userId, role, createdAt: Date.now() }));
    return sessionId;
  }

  getSession(sessionId) {
    if (typeof sessionId !== 'string' || sessionId.length !== 64) return null;
    return this.sessions.get(sessionId) || null;
  }

  revokeSession(sessionId) {
    this.sessions.delete(sessionId);
  }
}

class PolicyEngine {
  constructor() {
    this.policies = new Map();
  }

  loadPolicy(policyDoc) {
    if (typeof policyDoc !== 'object' || policyDoc === null || Array.isArray(policyDoc)) {
      throw new Error('Invalid policy document');
    }
    if (typeof policyDoc.name !== 'string' || policyDoc.name.length === 0) {
      throw new Error('Policy must have a name');
    }
    if (!Array.isArray(policyDoc.rules)) {
      throw new Error('Policy must have rules array');
    }
    // Validate each rule structure
    for (const rule of policyDoc.rules) {
      if (typeof rule !== 'object' || rule === null || Array.isArray(rule)) {
        throw new Error('Invalid rule structure');
      }
      if (typeof rule.role !== 'string' || !Object.values(ROLES).includes(rule.role)) {
        throw new Error('Invalid role in rule');
      }
      if (!Array.isArray(rule.actions) || !rule.actions.every(a => typeof a === 'string')) {
        throw new Error('Invalid actions in rule');
      }
      if (rule.effect !== 'allow' && rule.effect !== 'deny') {
        throw new Error('Invalid effect in rule');
      }
    }
    // Store a deep-frozen copy to prevent mutation
    const safeCopy = Object.freeze({
      name: String(policyDoc.name),
      rules: Object.freeze(policyDoc.rules.map(r => Object.freeze({
        role: String(r.role),
        actions: Object.freeze(r.actions.map(a => String(a))),
        effect: String(r.effect)
      })))
    });
    this.policies.set(safeCopy.name, safeCopy);
    return true;
  }

  evaluateAccess(role, action) {
    // Check all loaded policies for a matching allow rule
    for (const [policyName, policy] of this.policies) {
      if (!policy.rules) continue;
      for (const rule of policy.rules) {
        if (rule.role === role && rule.actions && rule.actions.includes(action)) {
          return rule.effect === 'allow';
        }
      }
    }
    // Default deny
    return false;
  }

  isAdminAction(action) {
    return ADMIN_ACTIONS.includes(action);
  }
}

class AuthorizationService {
  constructor() {
    this.sessionStore = new SessionStore();
    this.policyEngine = new PolicyEngine();
    this.auditLog = [];
    this._initDefaultPolicies();
  }

  _initDefaultPolicies() {
    this.policyEngine.loadPolicy({
      name: 'default_admin',
      rules: [
        { role: ROLES.ADMIN, actions: ['delete_user', 'modify_config', 'reset_system', 'read', 'write'], effect: 'allow' }
      ]
    });
    this.policyEngine.loadPolicy({
      name: 'default_user',
      rules: [
        { role: ROLES.USER, actions: ['read', 'write'], effect: 'allow' }
      ]
    });
    this.policyEngine.loadPolicy({
      name: 'default_auditor',
      rules: [
        { role: ROLES.AUDITOR, actions: ['read'], effect: 'allow' }
      ]
    });
  }

  authenticate(userId, password) {
    if (typeof userId !== 'string' || typeof password !== 'string') {
      return null;
    }
    if (userId.length < 1 || userId.length > 64) return null;
    if (password.length < 8 || password.length > 128) return null;
    // Reject any non-ASCII characters in userId
    if (!/^[a-zA-Z0-9_]+$/.test(userId)) return null;

    // Demo: assign role based on userId prefix
    let role = ROLES.USER;
    if (userId.startsWith('admin_')) role = ROLES.ADMIN;
    if (userId.startsWith('audit_')) role = ROLES.AUDITOR;

    return this.sessionStore.createSession(userId, role);
  }

  authorize(sessionId, action, resource) {
    const session = this.sessionStore.getSession(sessionId);
    if (!session) {
      return { granted: false, reason: 'invalid_session' };
    }

    if (typeof action !== 'string' || action.length === 0 || action.length > 64) {
      return { granted: false, reason: 'invalid_action' };
    }
    // Only allow known action characters
    if (!/^[a-z_]+$/.test(action)) {
      return { granted: false, reason: 'invalid_action' };
    }

    const role = session.role;

    // For admin actions, verify role is admin
    if (this.policyEngine.isAdminAction(action)) {
      if (role !== ROLES.ADMIN) {
        this._audit(session.userId, action, resource, false, 'insufficient_privilege');
        return { granted: false, reason: 'insufficient_privilege' };
      }
    }

    // Evaluate against policy engine
    const allowed = this.policyEngine.evaluateAccess(role, action);
    this._audit(session.userId, action, resource, allowed, allowed ? 'policy_allow' : 'policy_deny');
    return { granted: allowed, reason: allowed ? 'policy_allow' : 'policy_deny' };
  }

  _audit(userId, action, resource, granted, reason) {
    this.auditLog.push({
      timestamp: Date.now(),
      userId,
      action,
      resource: typeof resource === 'string' ? resource.slice(0, 256) : '',
      granted,
      reason
    });
  }
}

const authService = new AuthorizationService();

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/policy') {
    // Policy loading requires internal access only - check for internal header
    const internalToken = req.headers['x-internal-token'];
    if (!safeTokenEqual(internalToken, process.env.INTERNAL_SECRET)) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end('{"error":"forbidden"}');
      return;
    }
    let body = '';
    req.on('data', chunk => {
      if (body.length + chunk.length > 10240) {
        res.writeHead(413);
        res.end('{"error":"payload_too_large"}');
        return;
      }
      body += chunk;
    });
    req.on('end', () => {
      try {
        const policyDoc = JSON.parse(body);
        authService.policyEngine.loadPolicy(policyDoc);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"status":"policy_loaded"}');
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: e.message }));
      }
    });
  } else if (req.method === 'POST' && req.url === '/api/login') {
    let body = '';
    req.on('data', chunk => {
      if (body.length + chunk.length > 1024) {
        res.writeHead(413);
        res.end('{"error":"payload_too_large"}');
        return;
      }
      body += chunk;
    });
    req.on('end', () => {
      try {
        const { userId, password } = JSON.parse(body);
        const sessionId = authService.authenticate(userId, password);
        if (sessionId) {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ sessionId }));
        } else {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end('{"error":"auth_failed"}');
        }
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end('{"error":"invalid_request"}');
      }
    });
  } else if (req.method === 'POST' && req.url === '/api/authorize') {
    let body = '';
    req.on('data', chunk => {
      if (body.length + chunk.length > 1024) {
        res.writeHead(413);
        res.end('{"error":"payload_too_large"}');
        return;
      }
      body += chunk;
    });
    req.on('end', () => {
      try {
        const { sessionId, action, resource } = JSON.parse(body);
        const result = authService.authorize(sessionId, action, resource);
        res.writeHead(result.granted ? 200 : 403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end('{"error":"invalid_request"}');
      }
    });
  } else {
    res.writeHead(404);
    res.end('{"error":"not_found"}');
  }
});

server.listen(3000);
module.exports = { authService, server };
